cat > src/lib/milestones.ts <<'EOF'
import type { IsoTimestamp } from "@/types/common";
import type {
  Milestone,
  MilestoneProgress,
  MilestoneWithProgress,
} from "@/types/milestone";

/**
 * Milestone rules that need no database: the state-conflict error, name
 * normalisation for the per-project uniqueness check, the overdue predicate
 * and the listing order. The service layer composes these; nothing else
 * re-derives them.
 */

export type MilestoneStateReason =
  | "closed"
  | "already_open"
  | "too_many_open"
  | "name_taken";

const REASON_MESSAGES: Readonly<Record<MilestoneStateReason, string>> = {
  closed: "That milestone is closed.",
  already_open: "That milestone is already open.",
  too_many_open: "This project already has the maximum number of open milestones.",
  name_taken: "A milestone with that name already exists in this project.",
};

/** A milestone is in the wrong state for the requested operation. */
export class MilestoneStateError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly reason: MilestoneStateReason,
    detail?: string,
  ) {
    super(
      detail === undefined
        ? REASON_MESSAGES[reason]
        : `${REASON_MESSAGES[reason]} (${detail})`,
    );
    this.name = "MilestoneStateError";
  }
}

/** The comparison key behind "names are unique regardless of case and padding". */
export function normalizeMilestoneName(name: string): string {
  return name.trim().toLowerCase();
}

export function isMilestoneOpen(milestone: Milestone): boolean {
  return milestone.closedAt === null;
}

/**
 * Open, a target date strictly before `now`, and open issues left. A
 * milestone without a target date is never overdue.
 */
export function isMilestoneOverdue(
  milestone: Milestone,
  progress: MilestoneProgress,
  now: Date | IsoTimestamp,
): boolean {
  if (!isMilestoneOpen(milestone) || milestone.targetDate === null) {
    return false;
  }
  const at = typeof now === "string" ? Date.parse(now) : now.getTime();
  return Date.parse(milestone.targetDate) < at && progress.open > 0;
}

/**
 * Listing order: open before closed; then by target date, earliest first,
 * undated last. Equal keys compare as 0 so a stable sort over rows already in
 * creation order keeps the oldest first.
 */
export function compareMilestones(a: Milestone, b: Milestone): number {
  const openA = isMilestoneOpen(a);
  const openB = isMilestoneOpen(b);
  if (openA !== openB) return openA ? -1 : 1;

  if (a.targetDate === null || b.targetDate === null) {
    if (a.targetDate === b.targetDate) return 0;
    return a.targetDate === null ? 1 : -1;
  }

  return Date.parse(a.targetDate) - Date.parse(b.targetDate);
}

/** Sorts a creation-ordered list into the documented listing order. */
export function sortMilestones<T extends MilestoneWithProgress>(
  items: readonly T[],
): readonly T[] {
  return [...items].sort((a, b) => compareMilestones(a.milestone, b.milestone));
}
EOF

