/**
 * Milestone rows and the issue-side bookkeeping that hangs off them: progress counters and the close-time move of open issues.
 *
 * Must call (do not reimplement): shouldFilterArchived, normalizeMilestoneName
 */
import { and, asc, count, eq, inArray, isNull, ne, notInArray, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { normalizeMilestoneName } from "@/lib/milestones";
import { getDb, issues, milestones } from "@/server/db";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { toIsoTimestamp } from "@/types/common";
import { livePredicate, orgPredicate } from "./base-repository";
import { compact } from "./_paging";
import { brandId, toMilestone } from "./_mappers";
import type { UpdateMilestoneInput } from "@/schemas/milestone";
import type {
  IsoTimestamp,
  IssueId,
  MilestoneId,
  OrgId,
  ProjectId,
} from "@/types/common";
import type { Milestone, MilestoneProgress } from "@/types/milestone";

export async function findMilestoneById(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone | null> {
  const row = getDb()
    .select()
    .from(milestones)
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
    )
    .get();
  return row ? toMilestone(row) : null;
}

/** Every milestone of a project, open and closed, oldest first. */
export async function listMilestonesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly Milestone[]> {
  const rows = getDb()
    .select()
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
      ),
    )
    // `rowid` breaks ties between rows stamped in the same millisecond.
    .orderBy(asc(milestones.createdAt), sql`rowid`)
    .all();
  return rows.map(toMilestone);
}

export async function countOpenMilestones(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
        isNull(milestones.closedAt),
      ),
    )
    .get();
  return row?.value ?? 0;
}

/**
 * Whether `name` collides with another milestone of the project, closed ones
 * included. `exceptId` excludes the milestone being renamed.
 */
export async function isMilestoneNameTaken(
  orgId: OrgId,
  projectId: ProjectId,
  name: string,
  exceptId: MilestoneId | null = null,
): Promise<boolean> {
  const row = getDb()
    .select({ id: milestones.id })
    .from(milestones)
    .where(
      and(
        ...compact(
          orgPredicate(milestones.orgId, orgId),
          eq(milestones.projectId, projectId),
          eq(milestones.nameKey, normalizeMilestoneName(name)),
          exceptId === null ? undefined : ne(milestones.id, exceptId),
        ),
      ),
    )
    .get();
  return row !== undefined;
}

export async function insertMilestone(input: {
  orgId: OrgId;
  projectId: ProjectId;
  name: string;
  targetDate: IsoTimestamp | null;
}): Promise<Milestone> {
  const stamp = toIsoTimestamp(new Date());
  const name = input.name.trim();

  const row = getDb()
    .insert(milestones)
    .values({
      id: newId(),
      orgId: input.orgId,
      projectId: input.projectId,
      name,
      nameKey: normalizeMilestoneName(name),
      targetDate: input.targetDate,
      closedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toMilestone(row);
}

export async function updateMilestone(
  input: UpdateMilestoneInput,
): Promise<Milestone> {
  const name = input.name?.trim();

  const row = getDb()
    .update(milestones)
    .set({
      ...(name === undefined
        ? {}
        : { name, nameKey: normalizeMilestoneName(name) }),
      ...(input.targetDate === undefined
        ? {}
        : { targetDate: input.targetDate }),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(
        orgPredicate(milestones.orgId, input.orgId),
        eq(milestones.id, input.milestoneId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Milestone ${input.milestoneId} not found`);
  return toMilestone(row);
}

/**
 * Closes a milestone and, in the same transaction, moves its open live issues
 * to `moveTo` (or out of any milestone). Closed and archived issues stay put.
 */
export async function closeMilestone(
  orgId: OrgId,
  milestoneId: MilestoneId,
  moveTo: MilestoneId | null,
  now: Date = new Date(),
): Promise<{ milestone: Milestone; movedIssueIds: readonly IssueId[] }> {
  const stamp = toIsoTimestamp(now);

  return getDb().transaction((tx) => {
    const moved = tx
      .update(issues)
      .set({ milestoneId: moveTo, updatedAt: stamp })
      .where(
        and(
          ...compact(
            orgPredicate(issues.orgId, orgId),
            eq(issues.milestoneId, milestoneId),
            livePredicate(issues.archivedAt, {}),
            notInArray(issues.status, [...CLOSED_ISSUE_STATUSES]),
          ),
        ),
      )
      .returning({ id: issues.id })
      .all();

    const row = tx
      .update(milestones)
      .set({ closedAt: stamp, updatedAt: stamp })
      .where(
        and(
          orgPredicate(milestones.orgId, orgId),
          eq(milestones.id, milestoneId),
        ),
      )
      .returning()
      .get();

    if (!row) throw new Error(`Milestone ${milestoneId} not found`);

    return {
      milestone: toMilestone(row),
      movedIssueIds: moved.map((issue) => brandId<IssueId>(issue.id)),
    };
  });
}

export async function reopenMilestone(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  const row = getDb()
    .update(milestones)
    .set({ closedAt: null, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Milestone ${milestoneId} not found`);
  return toMilestone(row);
}

/**
 * Total/open/closed counters over each milestone's live issues, keyed by
 * milestone id. Milestones without issues still get a zeroed entry.
 */
export async function getMilestoneProgress(
  orgId: OrgId,
  milestoneIds: readonly MilestoneId[],
): Promise<Readonly<Record<string, MilestoneProgress>>> {
  const progress: Record<string, { total: number; open: number; closed: number }> =
    {};
  for (const id of milestoneIds) {
    progress[id] = { total: 0, open: 0, closed: 0 };
  }
  if (milestoneIds.length === 0) return progress;

  const rows = getDb()
    .select({
      milestoneId: issues.milestoneId,
      status: issues.status,
      value: count(),
    })
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          inArray(issues.milestoneId, [...milestoneIds]),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .groupBy(issues.milestoneId, issues.status)
    .all();

  for (const row of rows) {
    if (row.milestoneId === null) continue;
    const entry = progress[row.milestoneId];
    if (entry === undefined) continue;

    entry.total += row.value;
    if (CLOSED_ISSUE_STATUSES.includes(row.status)) {
      entry.closed += row.value;
    } else {
      entry.open += row.value;
    }
  }

  return progress;
}

