export async function getMilestoneProgress(
  orgId: OrgId,
  milestoneIds: readonly MilestoneId[],
): Promise<Readonly<Record<string, MilestoneProgress>>> {
  const progress: Record<string, { total: number; open: number; closed: number }> =
    {};
  for (const id of milestoneIds) {
    progress[id] = { total: 0, open: 0, closed: 0 };
  }
  if (milestoneIds.length === 0) return progress;

  const rows = getDb()
    .select({
      milestoneId: issues.milestoneId,
      status: issues.status,
      value: count(),
