    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          inArray(issues.milestoneId, [...milestoneIds]),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .groupBy(issues.milestoneId, issues.status)
    .all();

  for (const row of rows) {
    if (row.milestoneId === null) continue;
    const entry = progress[row.milestoneId];
    if (entry === undefined) continue;

    entry.total += row.value;
    if (CLOSED_ISSUE_STATUSES.includes(row.status)) {
      entry.closed += row.value;
    } else {
      entry.open += row.value;
    }
  }

