/**
 * Milestone lifecycle: per-project name uniqueness, the open-milestone cap, progress and the close-time move of open issues.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, assertNotArchived, emit
 */
import { MAX_OPEN_MILESTONES_PER_PROJECT } from "@/config/constants";
import { emit } from "@/lib/event-bus";
import {
  MilestoneStateError,
  isMilestoneOpen,
  isMilestoneOverdue,
  sortMilestones,
} from "@/lib/milestones";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as milestoneRepo from "@/server/repositories/milestone-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import {
  NotFoundError,
  actorEnvelope,
  projectResource,
  requireFound,
} from "./_support";
import type {
  CloseMilestoneInput,
  CreateMilestoneInput,
  UpdateMilestoneInput,
} from "@/schemas/milestone";
import type { IssueId, MilestoneId, OrgId, ProjectId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { Milestone, MilestoneWithProgress } from "@/types/milestone";
import type { Project } from "@/types/project";

/**
 * The moved-issue alerts are part of the notification fan-out, which attaches
 * itself when its module is first imported.
 */
import "./notification-service";

export async function createMilestone(
  actor: Actor,
  input: CreateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  await assertNameFree(input.orgId, project.id, input.name, null);
  await assertRoomForOpenMilestone(input.orgId, project.id);

  const milestone = await milestoneRepo.insertMilestone({
    orgId: input.orgId,
    projectId: project.id,
    name: input.name,
    targetDate: input.targetDate ?? null,
  });

  await emit("milestone.created", {
    ...actorEnvelope(actor),
    milestoneId: milestone.id,
    projectId: milestone.projectId,
  });

  return milestone;
}

/** Renames and re-dates; open and closed milestones alike. */
export async function updateMilestone(
  actor: Actor,
  input: UpdateMilestoneInput,
): Promise<Milestone> {
  const { milestone } = await loadForWrite(
    actor,
    input.orgId,
    input.milestoneId,
  );

  if (input.name !== undefined) {
    await assertNameFree(
      input.orgId,
      milestone.projectId,
      input.name,
      milestone.id,
    );
  }

  return milestoneRepo.updateMilestone(input);
}

/**
 * Closes a milestone. Its open live issues move to `moveOpenIssuesTo` — which
 * must be another open milestone of the same project — or out of any
 * milestone when none is named. Every check runs before anything is written.
 */
export async function closeMilestone(
  actor: Actor,
  input: CloseMilestoneInput,
): Promise<{ milestone: Milestone; movedIssueIds: readonly IssueId[] }> {
  const now = new Date();
  const { milestone } = await loadForWrite(
    actor,
    input.orgId,
    input.milestoneId,
  );

  if (!isMilestoneOpen(milestone)) {
    throw new MilestoneStateError("closed", milestone.id);
  }

  const moveTo = input.moveOpenIssuesTo ?? null;
  if (moveTo !== null) {
    if (moveTo === milestone.id) throw new NotFoundError("Milestone", moveTo);
    await requireOpenMilestone(input.orgId, milestone.projectId, moveTo);
  }

  const result = await milestoneRepo.closeMilestone(
    input.orgId,
    milestone.id,
    moveTo,
    now,
  );

  await emit("milestone.closed", {
    ...actorEnvelope(actor),
    milestoneId: result.milestone.id,
    projectId: result.milestone.projectId,
    movedToMilestoneId: moveTo,
    movedIssueIds: result.movedIssueIds,
  });

  return result;
}

export async function reopenMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  const { milestone } = await loadForWrite(actor, orgId, milestoneId);

  if (isMilestoneOpen(milestone)) {
    throw new MilestoneStateError("already_open", milestone.id);
  }
  await assertRoomForOpenMilestone(orgId, milestone.projectId);

  const reopened = await milestoneRepo.reopenMilestone(orgId, milestone.id);

  await emit("milestone.reopened", {
    ...actorEnvelope(actor),
    milestoneId: reopened.id,
    projectId: reopened.projectId,
  });

  return reopened;
}

/** Open milestones first, then closed; each by target date, undated last. */
export async function listMilestones(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly MilestoneWithProgress[]> {
  const now = new Date();
  assertOrgScope(actor, orgId);

  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "project:read", projectResource(project));

  const milestones = await milestoneRepo.listMilestonesForProject(
    orgId,
    project.id,
  );
  return sortMilestones(await withProgress(orgId, milestones, now));
}

export async function getMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<MilestoneWithProgress> {
  const now = new Date();
  assertOrgScope(actor, orgId);

  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  const project = requireFound(
    await projectRepo.findProjectById(orgId, milestone.projectId),
    "Project",
    milestone.projectId,
  );
  assertCan(actor, "project:read", projectResource(project));

  const [item] = await withProgress(orgId, [milestone], now);
  return requireFound(item, "Milestone", milestoneId);
}

/**
 * Resolves the milestone an issue is being put into: it must belong to
 * `projectId` (anything else, another workspace's included, reads as absent)
 * and be open.
 */
export async function requireOpenMilestone(
  orgId: OrgId,
  projectId: ProjectId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  const milestone = await milestoneRepo.findMilestoneById(orgId, milestoneId);
  if (milestone === null || milestone.projectId !== projectId) {
    throw new NotFoundError("Milestone", milestoneId);
  }
  if (!isMilestoneOpen(milestone)) {
    throw new MilestoneStateError("closed", milestone.id);
  }
  return milestone;
}

/**
 * The guard every milestone write shares: tenant scope, existence,
 * `project:update` on the owning project and a live project — the same gates,
 * in the same order, as `updateProject`.
 */
async function loadForWrite(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<{ milestone: Milestone; project: Project }> {
  assertOrgScope(actor, orgId);

  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  const project = requireFound(
    await projectRepo.findProjectById(orgId, milestone.projectId),
    "Project",
    milestone.projectId,
  );
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  return { milestone, project };
}

async function assertNameFree(
  orgId: OrgId,
  projectId: ProjectId,
  name: string,
  exceptId: MilestoneId | null,
): Promise<void> {
  if (await milestoneRepo.isMilestoneNameTaken(orgId, projectId, name, exceptId)) {
    throw new MilestoneStateError("name_taken", name.trim());
  }
}

async function assertRoomForOpenMilestone(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<void> {
  const open = await milestoneRepo.countOpenMilestones(orgId, projectId);
  if (open >= MAX_OPEN_MILESTONES_PER_PROJECT) {
    throw new MilestoneStateError(
      "too_many_open",
      `${open} of ${MAX_OPEN_MILESTONES_PER_PROJECT}`,
    );
  }
}

async function withProgress(
  orgId: OrgId,
  milestones: readonly Milestone[],
  now: Date,
): Promise<readonly MilestoneWithProgress[]> {
  const progress = await milestoneRepo.getMilestoneProgress(
    orgId,
    milestones.map((milestone) => milestone.id),
  );

  return milestones.map((milestone) => {
    const counts = progress[milestone.id] ?? { total: 0, open: 0, closed: 0 };
    return {
      milestone,
      progress: counts,
      overdue: isMilestoneOverdue(milestone, counts, now),
    };
  });
}

