import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as milestoneRepo from "@/server/repositories/milestone-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import {
  NotFoundError,
  actorEnvelope,
  projectResource,
  requireFound,
} from "./_support";
import type {
  CloseMilestoneInput,
  CreateMilestoneInput,
  UpdateMilestoneInput,
} from "@/schemas/milestone";
import type { IssueId, MilestoneId, OrgId, ProjectId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { Milestone, MilestoneWithProgress } from "@/types/milestone";
import type { Project } from "@/types/project";

/**
 * The moved-issue alerts are part of the notification fan-out, which attaches
 * itself when its module is first imported.
 */
import "./notification-service";

export async function createMilestone(
  actor: Actor,
  input: CreateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  await assertNameFree(input.orgId, project.id, input.name, null);
  await assertRoomForOpenMilestone(input.orgId, project.id);

  const milestone = await milestoneRepo.insertMilestone({
    orgId: input.orgId,
    projectId: project.id,
    name: input.name,
    targetDate: input.targetDate ?? null,
  });

  await emit("milestone.created", {
    ...actorEnvelope(actor),
    milestoneId: milestone.id,
    projectId: milestone.projectId,
  });

  return milestone;
}

/** Renames and re-dates; open and closed milestones alike. */
export async function updateMilestone(
  actor: Actor,
  input: UpdateMilestoneInput,
): Promise<Milestone> {
  const { milestone } = await loadForWrite(
    actor,
    input.orgId,
    input.milestoneId,
  );

  if (input.name !== undefined) {
    await assertNameFree(
      input.orgId,
      milestone.projectId,
      input.name,
      milestone.id,
    );
  }

  return milestoneRepo.updateMilestone(input);
}

/**
 * Closes a milestone. Its open live issues move to `moveOpenIssuesTo` — which
 * must be another open milestone of the same project — or out of any
 * milestone when none is named. Every check runs before anything is written.
 */
export async function closeMilestone(
  actor: Actor,
  input: CloseMilestoneInput,
): Promise<{ milestone: Milestone; movedIssueIds: readonly IssueId[] }> {
  const now = new Date();
  const { milestone } = await loadForWrite(
    actor,
    input.orgId,
    input.milestoneId,
  );

  if (!isMilestoneOpen(milestone)) {
    throw new MilestoneStateError("closed", milestone.id);
  }

  const moveTo = input.moveOpenIssuesTo ?? null;
  if (moveTo !== null) {
    if (moveTo === milestone.id) throw new NotFoundError("Milestone", moveTo);
    await requireOpenMilestone(input.orgId, milestone.projectId, moveTo);
  }

  const result = await milestoneRepo.closeMilestone(
    input.orgId,
    milestone.id,
    moveTo,
    now,
  );

  await emit("milestone.closed", {
    ...actorEnvelope(actor),
    milestoneId: result.milestone.id,
    projectId: result.milestone.projectId,
    movedToMilestoneId: moveTo,
    movedIssueIds: result.movedIssueIds,
  });

  return result;
}

export async function reopenMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  const { milestone } = await loadForWrite(actor, orgId, milestoneId);

  if (isMilestoneOpen(milestone)) {
    throw new MilestoneStateError("already_open", milestone.id);
  }
  await assertRoomForOpenMilestone(orgId, milestone.projectId);

  const reopened = await milestoneRepo.reopenMilestone(orgId, milestone.id);

  await emit("milestone.reopened", {
    ...actorEnvelope(actor),
    milestoneId: reopened.id,
    projectId: reopened.projectId,
  });

  return reopened;
}

