let projectCounter = 0;

function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(subscribe(type, (payload) => void seen.push(payload)));
  return seen;
}

async function freshProject(owner: Tenant = tenant): Promise<Project> {
  projectCounter += 1;
  return projectRepo.insertProject({
    orgId: owner.org.id,
    name: `Project ${projectCounter}`,
    slug: `project-${projectCounter}`,
    key: `P${projectCounter}`,
    description: null,
    visibility: "org",
    leadId: owner.userIds.owner,
    color: "#6366f1",
    targetDate: null,
  });
}

function milestoneInput(
  project: Project,
  name: string,
  targetDate: string | null = null,
) {
  return {
    orgId: project.orgId,
    projectId: project.id,
    name,
    targetDate: targetDate as IsoTimestamp | null,
  };
}

const PAST = "2020-01-01T00:00:00.000Z";
const FUTURE = "2099-01-01T00:00:00.000Z";

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("milestones");
  other = await createTenant("milestones-other");
  detachActivity = registerActivityListeners();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  detachActivity();
  cleanup();
});

describe("createMilestone", () => {
  it("creates an open milestone and announces it once", async () => {
    const project = await freshProject();
    const seen = capture("milestone.created");

    const milestone = await milestoneService.createMilestone(
      tenant.actors.member,
      milestoneInput(project, "Beta", FUTURE),
    );

    expect(milestone).toMatchObject({
      projectId: project.id,
      orgId: tenant.org.id,
      name: "Beta",
      targetDate: FUTURE,
      closedAt: null,
    });
    expect(seen).toEqual([
      expect.objectContaining({
        milestoneId: milestone.id,
        projectId: project.id,
        actorId: tenant.userIds.member,
      }),
    ]);
  });

  it("applies the guards", async () => {
    const project = await freshProject();

    await expect(
      milestoneService.createMilestone(tenant.actors.viewer, milestoneInput(project, "V")),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      milestoneService.createMilestone(other.actors.owner, milestoneInput(project, "X")),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      milestoneService.createMilestone(tenant.actors.owner, {
        ...milestoneInput(project, "X"),
        projectId: other.project.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("keeps names unique per project regardless of case and padding, closed ones included", async () => {
    const project = await freshProject();
    const first = await milestoneService.createMilestone(
      tenant.actors.member,
      milestoneInput(project, "Launch"),
    );
    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: first.id,
      moveOpenIssuesTo: null,
    });

    const attempt = milestoneService.createMilestone(
      tenant.actors.member,
      milestoneInput(project, "  LAUNCH "),
    );
    await expect(attempt).rejects.toBeInstanceOf(MilestoneStateError);
    await expect(attempt).rejects.toMatchObject({ reason: "name_taken", code: "conflict" });

    const elsewhere = await freshProject();
    await expect(
      milestoneService.createMilestone(tenant.actors.member, milestoneInput(elsewhere, "launch")),
    ).resolves.toMatchObject({ name: "launch" });
  });

  it("refuses more than the open cap, but closed milestones do not count", async () => {
    const project = await freshProject();
    const created = [];
    for (let i = 0; i < MAX_OPEN_MILESTONES_PER_PROJECT; i += 1) {
      created.push(
        await milestoneService.createMilestone(
          tenant.actors.member,
          milestoneInput(project, `M${i}`),
        ),
      );
    }

    await expect(
      milestoneService.createMilestone(tenant.actors.member, milestoneInput(project, "extra")),
    ).rejects.toMatchObject({ reason: "too_many_open" });

    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: created[0]!.id,
      moveOpenIssuesTo: null,
    });
    const extra = await milestoneService.createMilestone(
      tenant.actors.member,
      milestoneInput(project, "extra"),
    );

    await expect(
      milestoneService.reopenMilestone(tenant.actors.member, tenant.org.id, created[0]!.id),
    ).rejects.toMatchObject({ reason: "too_many_open" });

    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: extra.id,
      moveOpenIssuesTo: null,
    });
    await expect(
      milestoneService.reopenMilestone(tenant.actors.member, tenant.org.id, created[0]!.id),
    ).resolves.toMatchObject({ closedAt: null });
  });
});

describe("updateMilestone", () => {
  it("renames, re-dates and rejects a taken name", async () => {
    const project = await freshProject();
    const a = await milestoneService.createMilestone(tenant.actors.member, milestoneInput(project, "A"));
    await milestoneService.createMilestone(tenant.actors.member, milestoneInput(project, "B"));

    const renamed = await milestoneService.updateMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: a.id,
      name: "a",
      targetDate: FUTURE as IsoTimestamp,
    });
    expect(renamed).toMatchObject({ name: "a", targetDate: FUTURE });

    await expect(
      milestoneService.updateMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        milestoneId: a.id,
        name: " b",
      }),
    ).rejects.toMatchObject({ reason: "name_taken" });

    const cleared = await milestoneService.updateMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: a.id,
      targetDate: null,
    });
    expect(cleared).toMatchObject({ name: "a", targetDate: null });
  });
});

describe("issues in milestones", () => {
  it("puts an issue into a milestone at creation and later, within its own project only", async () => {
    const project = await freshProject();
    const m1 = await milestoneService.createMilestone(tenant.actors.member, milestoneInput(project, "One"));
    const m2 = await milestoneService.createMilestone(tenant.actors.member, milestoneInput(project, "Two"));
    const foreign = await milestoneService.createMilestone(
      tenant.actors.member,
      milestoneInput(await freshProject(), "Foreign"),
    );

    const issue = await issueService.createIssue(tenant.actors.member, {
      ...issueInput(tenant.org.id, project.id),
      milestoneId: m1.id,
    });
    expect(issue.milestoneId).toBe(m1.id);

    const moved = await issueService.setIssueMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      milestoneId: m2.id,
    });
    expect(moved.milestoneId).toBe(m2.id);

    await expect(
      issueService.setIssueMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        milestoneId: foreign.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    const out = await issueService.setIssueMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      milestoneId: null,
    });
    expect(out.milestoneId).toBeNull();
  });

  it("refuses a closed milestone at creation without creating anything", async () => {
    const project = await freshProject();
    const closed = await milestoneService.createMilestone(tenant.actors.member, milestoneInput(project, "Done"));
    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: closed.id,
      moveOpenIssuesTo: null,
    });

    const seen = capture("issue.created");
    await expect(
      issueService.createIssue(tenant.actors.member, {
        ...issueInput(tenant.org.id, project.id),
        milestoneId: closed.id,
      }),
    ).rejects.toMatchObject({ reason: "closed" });
    expect(seen).toHaveLength(0);

    const board = await issueService.getBoard(tenant.actors.member, tenant.org.id, project.id);
    expect(board.reduce((sum, column) => sum + column.total, 0)).toBe(0);
  });

  it("refuses to move an archived issue", async () => {
    const project = await freshProject();
    const m = await milestoneService.createMilestone(tenant.actors.member, milestoneInput(project, "M"));
    const issue = await issueService.createIssue(tenant.actors.member, issueInput(tenant.org.id, project.id));
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);

    await expect(
      issueService.setIssueMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        milestoneId: m.id,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
  });
});

describe("progress, overdue and ordering", () => {
  it("counts live issues and flags overdue only with open issues and a past date", async () => {
    const project = await freshProject();
    const m = await milestoneService.createMilestone(
      tenant.actors.member,
      milestoneInput(project, "Late", PAST),
    );

    const mk = () =>
      issueService.createIssue(tenant.actors.member, {
        ...issueInput(tenant.org.id, project.id),
        milestoneId: m.id,
      });
    const a = await mk();
    const b = await mk();
    const c = await mk();
    await mk();
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: a.id,
      status: "done",
    });
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: b.id,
      status: "canceled",
    });
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, c.id);

    const got = await milestoneService.getMilestone(tenant.actors.viewer, tenant.org.id, m.id);
    expect(got.progress).toEqual({ total: 3, open: 1, closed: 2 });
    expect(got.overdue).toBe(true);
  });

  it("lists open first, then closed; by target date with undated last; ties oldest first", async () => {
    const project = await freshProject();
    const make = (name: string, date: string | null) =>
      milestoneService.createMilestone(tenant.actors.member, milestoneInput(project, name, date));

    const undated1 = await make("undated-1", null);
    const late = await make("late", "2030-06-01T00:00:00.000Z");
    const early = await make("early", "2030-01-01T00:00:00.000Z");
    const undated2 = await make("undated-2", null);
    const closedEarly = await make("closed-early", "2029-01-01T00:00:00.000Z");
    const closedUndated = await make("closed-undated", null);
    for (const m of [closedUndated, closedEarly]) {
      await milestoneService.closeMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        milestoneId: m.id,
        moveOpenIssuesTo: null,
      });
    }

    const list = await milestoneService.listMilestones(tenant.actors.viewer, tenant.org.id, project.id);
    expect(list.map((item) => item.milestone.id)).toEqual([
      early.id,
      late.id,
      undated1.id,
      undated2.id,
      closedEarly.id,
      closedUndated.id,
    ]);
    expect(list.every((item) => item.overdue === false)).toBe(true);
  });
});

describe("closeMilestone", () => {
  it("moves open live issues, alerts their assignees once and records the audit row", async () => {
    const project = await freshProject();
    const from = await milestoneService.createMilestone(tenant.actors.member, milestoneInput(project, "From"));
    const to = await milestoneService.createMilestone(tenant.actors.member, milestoneInput(project, "To"));

    const issue = (assigneeId: Tenant["userIds"]["admin"] | null) =>
      issueService.createIssue(tenant.actors.owner, {
        ...issueInput(tenant.org.id, project.id, { assigneeId }),
        milestoneId: from.id,
      });
    const forAdmin = await issue(tenant.userIds.admin);
    const forCloser = await issue(tenant.userIds.member);
    const unassigned = await issue(null);
    const finished = await issue(tenant.userIds.admin);
    const archived = await issue(tenant.userIds.admin);
    await issueService.changeIssueStatus(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: finished.id,
      status: "done",
    });
    await issueService.archiveIssue(tenant.actors.owner, tenant.org.id, archived.id);

    const before = await notificationRepo.listNotifications({
      orgId: tenant.org.id,
      recipientId: tenant.userIds.admin,
      unreadOnly: false,
      kind: ["issue_milestone_changed"],
      limit: 100,
      cursor: null,
    });

    const seen = capture("milestone.closed");
    const result = await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: from.id,
      moveOpenIssuesTo: to.id,
    });

    expect([...result.movedIssueIds].sort()).toEqual(
      [forAdmin.id, forCloser.id, unassigned.id].sort(),
    );
    expect(result.milestone.closedAt).not.toBeNull();
    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({ milestoneId: from.id, movedToMilestoneId: to.id });

    const fromAfter = await milestoneService.getMilestone(tenant.actors.member, tenant.org.id, from.id);
    const toAfter = await milestoneService.getMilestone(tenant.actors.member, tenant.org.id, to.id);
    expect(fromAfter.progress).toEqual({ total: 1, open: 0, closed: 1 });
    expect(toAfter.progress).toEqual({ total: 3, open: 3, closed: 0 });

    const after = await notificationRepo.listNotifications({
      orgId: tenant.org.id,
      recipientId: tenant.userIds.admin,
      unreadOnly: false,
      kind: ["issue_milestone_changed"],
      limit: 100,
      cursor: null,
    });
    expect(after.total - before.total).toBe(1);

    const closer = await notificationRepo.listNotifications({
      orgId: tenant.org.id,
      recipientId: tenant.userIds.member,
      unreadOnly: false,
      kind: ["issue_milestone_changed"],
      limit: 100,
      cursor: null,
    });
    expect(closer.total).toBe(0);

    const audit = await listActivity(tenant.actors.owner, {
      orgId: tenant.org.id,
      action: ["milestone.closed"],
      subjectKind: "milestone",
      limit: 100,
      cursor: null,
    });
    expect(audit.items.filter((row) => row.subjectId === from.id)).toEqual([
      expect.objectContaining({
        actorId: tenant.userIds.member,
        projectId: project.id,
      }),
    ]);
  });

  it("validates the target and the state before changing anything", async () => {
    const project = await freshProject();
    const m = await milestoneService.createMilestone(tenant.actors.member, milestoneInput(project, "M"));
    const closed = await milestoneService.createMilestone(tenant.actors.member, milestoneInput(project, "C"));
    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: closed.id,
      moveOpenIssuesTo: null,
    });
    const foreign = await milestoneService.createMilestone(
      tenant.actors.member,
      milestoneInput(await freshProject(), "F"),
    );
    const seen = capture("milestone.closed");

    const close = (moveOpenIssuesTo: MilestoneId | null, id: MilestoneId = m.id) =>
      milestoneService.closeMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        milestoneId: id,
        moveOpenIssuesTo,
      });

    await expect(close(m.id)).rejects.toBeInstanceOf(NotFoundError);
    await expect(close(foreign.id)).rejects.toBeInstanceOf(NotFoundError);
    await expect(close(other.project.id as unknown as MilestoneId)).rejects.toBeInstanceOf(
      NotFoundError,
    );
    await expect(close(closed.id)).rejects.toMatchObject({ reason: "closed" });
    await expect(close(null, closed.id)).rejects.toMatchObject({ reason: "closed" });
    await expect(
      milestoneService.reopenMilestone(tenant.actors.member, tenant.org.id, m.id),
    ).rejects.toMatchObject({ reason: "already_open" });
    expect(seen).toHaveLength(0);

    const still = await milestoneService.getMilestone(tenant.actors.member, tenant.org.id, m.id);
    expect(still.milestone.closedAt).toBeNull();
  });

  it("refuses every write on an archived project but still lists", async () => {
    const project = await freshProject();
    const m = await milestoneService.createMilestone(tenant.actors.member, milestoneInput(project, "M"));
    const issue = await issueService.createIssue(tenant.actors.member, issueInput(tenant.org.id, project.id));
    await projectRepo.archiveProject(tenant.org.id, project.id);

    await expect(
      milestoneService.createMilestone(tenant.actors.member, milestoneInput(project, "N")),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(
      milestoneService.updateMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        milestoneId: m.id,
        name: "renamed",
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(
      milestoneService.closeMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        milestoneId: m.id,
        moveOpenIssuesTo: null,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(
      issueService.setIssueMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        milestoneId: m.id,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    const list = await milestoneService.listMilestones(tenant.actors.viewer, tenant.org.id, project.id);
    expect(list).toHaveLength(1);
  });
});

